1	/**
2	 * The u18g round of the `angular-super-productivity-v2-13-15` cell: the two
3	 * TypeScript-line families u18f named as the cheapest remaining, read with the
4	 * readings each one needs, and the production build attempted on the result.
5	 *
6	 * Neither is a library migration. TS1259 is the compiler objecting to a default
7	 * import of a package that gained `export =` typings between the two eras, and
8	 * the answer is a compiler flag rather than an edit to the line; TS2794 is the
9	 * compiler objecting to `resolve()` in an un-parameterised promise executor, and
10	 * naming the type argument that fixes it in the diagnostic text itself.
11	 *
12	 * What this driver measures is the evidence each capability refuses on. For the
13	 * flag: every bare default import in the application, every namespace import it
14	 * calls as a function, and — for each package so imported — the declaration
15	 * entry the installed package points at and whether that entry ends in an export
16	 * assignment or names an ES default. For the executors: nothing beyond the
17	 * modules the compiler itself named, because the whole of the evidence for
18	 * `void` is inside the executor.
19	 *
20	 * Nothing here decides what a flag or a type argument means. It decides which
21	 * tree is read and which tree is written.
22	 */
23	
24	import { readFile, writeFile } from 'node:fs/promises';
25	import { existsSync } from 'node:fs';
26	import * as path from 'pathe';
27	import {
28		enableSyntheticDefaultImports,
29		packageOfSpecifier,
30		parameteriseVoidPromiseExecutors,
31		readModuleInterop,
32		type ExportAssignmentReading,
33		type ModuleInteropReading,
34	} from '../../../frameworks/angular/src/index.ts';
35	import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
36	import { applyRound, type CapabilityOutcome } from './angular-super-productivity-u18c-run.ts';
37	
38	/** Every file below `root` with `extension`, in a stable order. */
39	async function filesBelow(root: string, extension: string): Promise<readonly string[]> {
40		const { readdir } = await import('node:fs/promises');
41		const found: string[] = [];
42		const walk = async (directory: string): Promise<void> => {
43			for (const entry of await readdir(directory, { withFileTypes: true })) {
44				const absolute = path.join(directory, entry.name);
45				if (entry.isDirectory()) await walk(absolute);
46				else if (entry.name.endsWith(extension)) found.push(absolute);
47			}
48		};
49		if (existsSync(root)) await walk(root);
50		return Object.freeze(found.sort());
51	}
52	
53	/** The `types` condition of an exports entry, however it is nested. */
54	function typesOf(value: unknown): string | null {
55		if (typeof value === 'string') return value.endsWith('.d.ts') ? value : null;
56		if (typeof value !== 'object' || value === null) return null;
57		const record = value as Record<string, unknown>;
58		for (const key of ['types', 'typings', 'default', 'import', 'require', 'node']) {
59			const found = typesOf(record[key]);
60			if (found !== null) return found;
61		}
62		return null;
63	}
64	
65	/**
66	 * What one installed package's declaration entry says about how it may be
67	 * imported.
68	 *
69	 * The two facts are read off the entry file's own text: `export = X` is the
70	 * shape that makes a default import illegal without the flag, and
71	 * `export default` is the shape that makes it legal without one. A package with
72	 * no declaration entry is recorded as such rather than guessed at — an untyped
73	 * import raises no TS1259 and demands nothing.
74	 */
75	async function readExportAssignment(
76		tree: string,
77		name: string,
78	): Promise<ExportAssignmentReading> {
79		const root = path.join(tree, 'node_modules', name);
80		const absent: ExportAssignmentReading = Object.freeze({
81			package: name,
82			version: 'unknown',
83			declarationFile: null,
84			exportAssignment: false,
85			esDefaultExport: false,
86			complete: false,
87		});
88		if (!existsSync(path.join(root, 'package.json'))) return absent;
89		const manifest = JSON.parse(await readFile(path.join(root, 'package.json'), 'utf8')) as Readonly<{
90			version?: unknown;
91			types?: unknown;
92			typings?: unknown;
93			exports?: unknown;
94		}>;
95		const version = typeof manifest.version === 'string' ? manifest.version : 'unknown';
96		const declared =
97			typeof manifest.types === 'string'
98				? manifest.types
99				: typeof manifest.typings === 'string'
100					? manifest.typings
101					: typesOf(manifest.exports);
102		// A package with no declared entry may still be typed by a sibling
103		// `index.d.ts`, which is what node's own resolution falls back to.
104		const fallback = existsSync(path.join(root, 'index.d.ts')) ? 'index.d.ts' : null;
105		const entry = declared ?? fallback;
106		if (entry === null)
107			return Object.freeze({ ...absent, version, complete: true });
108		const file = path.join(root, entry);
109		if (!existsSync(file)) return Object.freeze({ ...absent, version });
110		const source = await readFile(file, 'utf8');
111		return Object.freeze({
112			package: name,
113			version,
114			declarationFile: entry,
115			exportAssignment: /^export\s*=\s*/mu.test(source),
116			esDefaultExport: /^export\s+default\b/mu.test(source),
117			complete: true,
118		});
119	}
120	
121	/**
122	 * The synthetic-default-import round. Driven by the tree rather than by the log:
123	 * a compiler flag applies to every module in the program, so the reading that
124	 * justifies it has to be of every module too.
125	 */
126	async function interopRound(): Promise<CapabilityOutcome> {
127		const modules = await filesBelow(path.join(APPLIED_TREE, 'src'), '.ts');
128		const readings: ModuleInteropReading[] = [];
129		for (const file of modules) {
130			const source = await readFile(file, 'utf8');
131			readings.push(readModuleInterop(path.relative(APPLIED_TREE, file), source));
132		}
133		const wanted = new Set<string>();
134		for (const reading of readings)
135			for (const site of reading.defaultImports) wanted.add(packageOfSpecifier(site.specifier));
136		const packages: ExportAssignmentReading[] = [];
137		for (const name of [...wanted].sort())
138			packages.push(await readExportAssignment(APPLIED_TREE, name));
139	
140		const config = path.join(APPLIED_TREE, 'tsconfig.json');
141		const migration = enableSyntheticDefaultImports(
142			await readFile(config, 'utf8'),
143			readings,
144			packages,
145		);
146		const changed: string[] = [];
147		const changes: string[] = [];
148		if (migration.changed) {
149			await writeFile(config, migration.config);
150			changed.push('tsconfig.json');
151			for (const change of migration.changes)
152				changes.push(
153					`tsconfig.json: ${change.path} ${change.from ?? 'undeclared'} → ${change.to}, ` +
154						`required by ${change.requiredBy.join('; ')}`,
155				);
156		}
157		const defaults = readings.reduce((total, entry) => total + entry.defaultImports.length, 0);
158		const called = readings.reduce(
159			(total, entry) => total + entry.calledNamespaceImports.length,
160			0,
161		);
162		return Object.freeze({
163			capability:
164				`synthetic-default-import-interop, against ${String(modules.length)} modules ` +
165				`(${String(defaults)} bare default import(s), ${String(called)} called namespace ` +
166				`import(s)) and ${packages
167					.map(
168						(entry) =>
169							`'${entry.package}'@${entry.version} (${entry.declarationFile ?? 'no typings'}, ` +
170							`export =: ${String(entry.exportAssignment)}, export default: ` +
171							`${String(entry.esDefaultExport)})`,
172					)
173					.join(', ')}`,
174			filesChanged: Object.freeze(changed),
175			changes: Object.freeze(changes),
176			unhandled: Object.freeze(migration.unhandled),
177		});
178	}
179	
180	/** The promise-executor round, driven by the compiler's own TS2794 lines. */
181	async function voidExecutorRound(log: string): Promise<CapabilityOutcome> {
182		const wanted = new Set<string>();
183		for (const raw of log.split('\n')) {
184			const line = raw.trim();
185			if (!line.includes(' - error TS2794: ')) continue;
186			const head = line.split(' - error TS2794: ')[0] ?? '';
187			const parts = head.split(':');
188			if (parts.length < 3) continue;
189			wanted.add(parts.slice(0, -2).join(':').replace('Error: ', ''));
190		}
191		const changed: string[] = [];
192		const changes: string[] = [];
193		const unhandled: string[] = [];
194		for (const file of [...wanted].sort()) {
195			const absolute = path.join(APPLIED_TREE, file);
196			if (!existsSync(absolute) || !file.endsWith('.ts')) {
197				unhandled.push(`${file}: the diagnostic names a file the applied tree does not carry`);
198				continue;
199			}
200			const source = await readFile(absolute, 'utf8');
201			const migration = parameteriseVoidPromiseExecutors(file, source);
202			unhandled.push(...migration.unhandled);
203			if (!migration.changed) continue;
204			await writeFile(absolute, migration.source);
205			changed.push(file);
206			for (const change of migration.changes)
207				changes.push(
208					`${file} line ${String(change.line)}: new Promise(…) → new Promise<void>(…) ` +
209						`(${change.parameter}, ${String(change.callSites)} zero-argument settle(s))`,
210				);
211		}
212		return Object.freeze({
213			capability: `promise-executor-void-parameter, against ${String(wanted.size)} module(s) the compiler named`,
214			filesChanged: Object.freeze(changed),
215			changes: Object.freeze(changes),
216			unhandled: Object.freeze(unhandled.sort()),
217		});
218	}
219	
220	export async function main(): Promise<void> {
221		const log = await readFile(path.join(STAGE_DIRECTORY, process.argv[2] ?? 'build-5.log'), 'utf8');
222		const outcomes: CapabilityOutcome[] = [...(await applyRound())];
223		outcomes.push(await interopRound());
224		outcomes.push(await voidExecutorRound(log));
225		await writeFile(
226			path.join(STAGE_DIRECTORY, 'u18g-round.json'),
227			`${JSON.stringify(outcomes, null, '\t')}\n`,
228		);
229		for (const outcome of outcomes)
230			process.stdout.write(
231				`${outcome.capability}: ${String(outcome.filesChanged.length)} files changed, ` +
232					`${String(outcome.changes.length)} changes, ${String(outcome.unhandled.length)} refused\n`,
233			);
234	}
235	
236	if (process.argv[1]?.endsWith('angular-super-productivity-u18g-run.ts'))
237		main().catch((error: unknown) => {
238			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
239			process.exitCode = 1;
240		});
