    responsive: true,
    legend: {
      position: 'top',
    },
  };`,
		after: `  pieChartOptions: ChartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
    },
  };`,
		reason: CHART_OPTIONS_REASON,
