		for (const use of uses) {
			const args = nextCallOf(module, use);
			if (args === null) continue;
			if (args === 0) {
				zeroArgument += 1;
				continue;
			}
			refusal =
				`${name}.next is called at line ${String(lineOf(source, use.start))} with ` +
